ReviewM.full_source_canonical_joint_limit.{u_1} (K : Type u_1) [Field K] [NumberField K]
  [MeasurableSpace (MasulloGRH.HeckeAdeles K)] (addHaar : Measure (MasulloGRH.HeckeAdeles K))
  (mu : Measure (MasulloGRH.HeckeIdeleClasses K)) (a l r s : ℝ) (places : ℕ → FinitePlace K) (u v : ℕ → ↥(Lp ℂ 2 mu))
  (hc : Summable fun i => ‖u i‖ * ‖v i‖) :
  let W := JThetaAttachment.fullSourceSpan K addHaar mu (a + (l + r) / 2) ((r - l) / 2) s;
  have Theta := OAllCharacterClosure.fullSourceMap K addHaar mu (a + (l + r) / 2) ((r - l) / 2) s;
  let E := Q.IntegratedSourceCutoff.finiteSourceSpan 0 0 Theta;
  have S := (JThetaAttachment.fullThetaClosure K addHaar mu (a + (l + r) / 2) ((r - l) / 2) s).starProjection;
  have w := fun x => PIntervalConvolution.intervalHalfWeight l r s (Masullo.IdeleClassGeometry.classLog K x);
  have p := NDivisorialShells.descendedMask K places (NDivisorialShells.arithmeticIndentation K);
  have d := fun T x => ∑' (i : ℕ), HNormalizedKernel.haarKernel w 1 (↑↑((E T).starProjection (v i))) (↑↑(u i)) x x;
  have e := fun x => ∑' (i : ℕ), HNormalizedKernel.haarKernel w 1 (↑↑(S (v i))) (↑↑(u i)) x x;
  have mask := fun z => FSmoothCutoff.mask K z.1 (z.2 / z.1);
  Tendsto (fun z => ∫ (x : MasulloGRH.HeckeIdeleClasses K), ‖mask z.2 x * d z.1 x - e x‖ ∂mu)
      (atTop ×ˢ FPhysicalFilter.cutoffRegime) (𝓝 0) ∧
    Tendsto
      (fun z =>
        ∑' (j : Option ℕ),
          ‖∫ (x : MasulloGRH.HeckeIdeleClasses K), ↑(p j x) * (mask z.2 x * d z.1 x) ∂mu -
              ∫ (x : MasulloGRH.HeckeIdeleClasses K), ↑(p j x) * e x ∂mu‖)
      (atTop ×ˢ FPhysicalFilter.cutoffRegime) (𝓝 0)
